func newDoctorCmd(flags *rootFlags) *cobra.Command {
	var failOn string
	cmd := &cobra.Command{
		Use:   "doctor",
		Short: "Check CLI health",
		Example: `  orcarouter-pp-cli doctor
  orcarouter-pp-cli doctor --json
  orcarouter-pp-cli doctor --fail-on warn`,
		RunE: func(cmd *cobra.Command, args []string) error {
			report := map[string]any{}

			cfg, err := config.Load(flags.configPath)
			if err != nil {
				report["config"] = fmt.Sprintf("error: %s", err)
			} else {
				report["config"] = "ok"
				report["config_path"] = cfg.Path
				report["base_url"] = cfg.BaseURL
			}

			// Check auth
			header := ""
			if cfg != nil {
				header = cfg.AuthHeader()
				if header == "" {
					report["auth"] = "not configured"
					report["auth_hint"] = "export ORCAROUTER_API_KEY=<your-key>"
				} else {
					report["auth"] = "configured"
					report["auth_source"] = cfg.AuthSource
				}
			}

			// Check connectivity by probing /models with the configured client.
			network := "ok"
			status := 0
			if cfg != nil {
				c := client.New(cfg, flags.timeout)
				var list client.ModelList
				if err := c.GetJSON("/models", &list); err != nil {
					network = fmt.Sprintf("error: %s", err)
					report["network"] = network
					report["reachable"] = false
				} else {
					report["network"] = "ok"
					report["reachable"] = true
					report["model_count"] = len(list.Data)
				}
			}

			if failOn == "warn" && network != "ok" {
				status = 1
			}
			if failOn == "error" && network != "ok" {
				status = 2
			}

			if flags.asJSON {
				if err := flags.printJSON(cmd, report); err != nil {
					return err
				}
			} else {
				for k, v := range report {
					fmt.Fprintf(cmd.OutOrStdout(), "%s: %v\n", k, v)
				}
			}
			if status != 0 {
				return exitCodeError(status)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&failOn, "fail-on", "", "Exit non-zero when health is worse than the given level (warn or error)")
	return cmd
}

func exitCodeError(code int) error {
	return &cliError{code: code}
}

